import React, { useState } from 'react';
import { Bus, Lock, User, ShieldCheck, ArrowRight, AlertCircle } from 'lucide-react';

// Mock user database with assigned roles
const registeredUsers = [
  {
    emailOrPhone: 'user@gmail.com',
    password: 'user123',
    name: 'Rahim Ahmed',
    role: 'passenger', // Passenger account
  },
  {
    emailOrPhone: 'admin@gmail.com',
    password: 'admin123',
    name: 'Admin Supervisor',
    role: 'admin', // Admin account
  },
];

export default function Signin({ onLoginSuccess }) {
  const [selectedRole, setSelectedRole] = useState('passenger'); // 'passenger' or 'admin'
  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  const handleSignIn = (e) => {
    e.preventDefault();
    setErrorMessage('');

    // 1. Basic validation
    if (!identifier || !password) {
      setErrorMessage('Please fill in all fields.');
      return;
    }

    // 2. Find user in database
    const foundUser = registeredUsers.find(
      (u) => u.emailOrPhone.toLowerCase() === identifier.toLowerCase().trim()
    );

    if (!foundUser) {
      setErrorMessage('Account not found. Please check your details.');
      return;
    }

    // 3. Verify password
    if (foundUser.password !== password) {
      setErrorMessage('Incorrect password. Please try again.');
      return;
    }

    // 4. Strict Role Validation
    if (foundUser.role !== selectedRole) {
      if (selectedRole === 'admin') {
        setErrorMessage('This account is registered as a Passenger. Please switch to the Passenger tab to sign in.');
      } else {
        setErrorMessage('This account is registered as an Administrator. Please switch to the Admin tab to sign in.');
      }
      return;
    }

    // 5. Successful login
    onLoginSuccess(foundUser);
  };

  const handleForgotPassword = () => {
    alert(`A password reset link has been sent to ${identifier || 'your email/phone'}.`);
  };

  return (
    <div style={styles.pageWrapper}>
      <div style={styles.card}>
        {/* Header */}
        <div style={styles.header}>
          <div style={styles.logoBadge}>
            <Bus size={28} color="#ea580c" />
          </div>
          <h2 style={styles.title}>ONLINE BUS BANGLADESH</h2>
          <p style={styles.subtitle}>Sign in to access your dashboard</p>
        </div>

        {/* Role Switcher Tabs */}
        <div style={styles.roleTabs}>
          <button
            type="button"
            onClick={() => {
              setSelectedRole('passenger');
              setErrorMessage('');
            }}
            style={{
              ...styles.tabBtn,
              ...(selectedRole === 'passenger' ? styles.activeTabBtn : {}),
            }}
          >
            <User size={16} /> Passenger Sign In
          </button>

          <button
            type="button"
            onClick={() => {
              setSelectedRole('admin');
              setErrorMessage('');
            }}
            style={{
              ...styles.tabBtn,
              ...(selectedRole === 'admin' ? styles.activeTabBtn : {}),
            }}
          >
            <ShieldCheck size={16} /> Admin Sign In
          </button>
        </div>

        {/* Error Alert */}
        {errorMessage && (
          <div style={styles.errorBox}>
            <AlertCircle size={18} color="#ef4444" />
            <span>{errorMessage}</span>
          </div>
        )}

        {/* Sign In Form */}
        <form onSubmit={handleSignIn} style={styles.form}>
          {/* Email / Phone Field */}
          <div style={styles.fieldGroup}>
            <label style={styles.label}>
              {selectedRole === 'admin' ? 'Admin ID / Email' : 'Email or Phone Number'}
            </label>
            <div style={styles.inputContainer}>
              <User size={18} color="#a1a1aa" />
              <input
                type="text"
                placeholder={selectedRole === 'admin' ? 'admin@gmail.com' : 'user@gmail.com'}
                value={identifier}
                onChange={(e) => setIdentifier(e.target.value)}
                style={styles.input}
              />
            </div>
          </div>

          {/* Password Field */}
          <div style={styles.fieldGroup}>
            <label style={styles.label}>Password</label>
            <div style={styles.inputContainer}>
              <Lock size={18} color="#a1a1aa" />
              <input
                type="password"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                style={styles.input}
              />
            </div>

            {/* Forgot Password Option Under Password */}
            <div style={styles.forgotWrapper}>
              <button
                type="button"
                onClick={handleForgotPassword}
                style={styles.forgotBtn}
              >
                Forgot password?
              </button>
            </div>
          </div>

          {/* Submit Button */}
          <button type="submit" style={styles.submitBtn}>
            <span>Sign In as {selectedRole === 'admin' ? 'Admin' : 'Passenger'}</span>
            <ArrowRight size={18} />
          </button>
        </form>

        {/* Credentials Helper Box */}
        <div style={styles.demoBox}>
          <p style={styles.demoTitle}>Demo Logins:</p>
          <p>Passenger: <strong>user@gmail.com</strong> / <strong>user123</strong></p>
          <p>Admin: <strong>admin@gmail.com</strong> / <strong>admin123</strong></p>
        </div>
      </div>
    </div>
  );
}

const styles = {
  pageWrapper: {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#09090b',
    padding: '20px',
  },
  card: {
    width: '100%',
    maxWidth: '420px',
    backgroundColor: '#18181b',
    border: '1px solid #27272a',
    borderRadius: '16px',
    padding: '32px',
    boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.5)',
  },
  header: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    marginBottom: '24px',
    textAlign: 'center',
  },
  logoBadge: {
    backgroundColor: '#27272a',
    padding: '12px',
    borderRadius: '12px',
    marginBottom: '12px',
    border: '1px solid #3f3f46',
  },
  title: {
    fontSize: '1.2rem',
    fontWeight: '800',
    color: '#ffffff',
    letterSpacing: '0.5px',
    margin: '0 0 4px 0',
  },
  subtitle: {
    fontSize: '0.85rem',
    color: '#a1a1aa',
    margin: 0,
  },
  roleTabs: {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
    gap: '6px',
    backgroundColor: '#27272a',
    padding: '4px',
    borderRadius: '10px',
    marginBottom: '20px',
  },
  tabBtn: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '6px',
    padding: '10px',
    border: 'none',
    borderRadius: '8px',
    backgroundColor: 'transparent',
    color: '#a1a1aa',
    fontSize: '0.8rem',
    fontWeight: '600',
    cursor: 'pointer',
    transition: 'all 0.2s',
  },
  activeTabBtn: {
    backgroundColor: '#ea580c',
    color: '#ffffff',
    boxShadow: '0 2px 8px rgba(234, 88, 12, 0.4)',
  },
  errorBox: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    backgroundColor: 'rgba(239, 68, 68, 0.1)',
    border: '1px solid rgba(239, 68, 68, 0.3)',
    color: '#f87171',
    padding: '12px',
    borderRadius: '8px',
    fontSize: '0.85rem',
    marginBottom: '20px',
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: '18px',
  },
  fieldGroup: {
    display: 'flex',
    flexDirection: 'column',
    gap: '6px',
  },
  label: {
    fontSize: '0.8rem',
    fontWeight: '600',
    color: '#e4e4e7',
  },
  inputContainer: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    backgroundColor: '#09090b',
    border: '1px solid #3f3f46',
    borderRadius: '8px',
    padding: '10px 14px',
  },
  input: {
    background: 'none',
    border: 'none',
    outline: 'none',
    color: '#ffffff',
    width: '100%',
    fontSize: '0.9rem',
  },
